1	package shadow
2	
3	import (
4		"encoding/json"
5		"errors"
6		"os"
7		"path/filepath"
8		"testing"
9		"time"
10	)
11	
12	// rbSpec 返回一个开启安装失败回滚的单设备活动规格（窗口 12:00–13:00，截止 14:00）。
13	func rbSpec() CampaignSpec {
14		spec := upSpec()
15		spec.Devices = []string{"d1"}
16		spec.BatchSize = 1
17		spec.RollbackOnFailure = true
18		return spec
19	}
20	
21	// awaitRollback 完成下载并令安装失败，使开启回滚活动中的设备进入等待回滚。
22	// 时间线（相对 at）：领取下载 at、下载成功 at+1m、领取安装 at+2m、安装失败 at+3m。
23	// 返回安装操作标识与安装失败被接受的时间。
24	func awaitRollback(t *testing.T, s *Store, spec CampaignSpec, id string, at time.Time) (string, time.Time) {
25		t.Helper()
26		dl, err := s.Claim(spec.ID, id, at)
27		if err != nil || dl == nil || dl.Kind != StageDownload {
28			t.Fatalf("claim download: %v %+v", err, dl)
29		}
30		if err := s.SubmitResult(OperationResult{
31			CampaignID: spec.ID, DeviceID: id, OperationID: dl.ID,
32			At: at.Add(time.Minute), Success: true,
33		}); err != nil {
34			t.Fatalf("download result: %v", err)
35		}
36		in, err := s.Claim(spec.ID, id, at.Add(2*time.Minute))
37		if err != nil || in == nil || in.Kind != StageInstall {
38			t.Fatalf("claim install: %v %+v", err, in)
39		}
40		failAt := at.Add(3 * time.Minute)
41		if err := s.SubmitResult(OperationResult{
42			CampaignID: spec.ID, DeviceID: id, OperationID: in.ID,
43			At: failAt, Success: false, Reason: "install broken",
44		}); err != nil {
45			t.Fatalf("install failure: %v", err)
46		}
47		return in.ID, failAt
48	}
49	
50	// 未开启回滚（默认）时安装失败沿用现有行为：设备直接失败，不锁定/等待回滚。
51	func TestRollbackDisabledKeepsLegacyBehavior(t *testing.T) {
52		s := setupUpgrade(t, "d1")
53		spec := upSpec()
54		spec.Devices = []string{"d1"}
55		spec.BatchSize = 1
56		createCampaign(t, s, spec)
57		bringOnline(t, s, "d1")
58	
59		_, failAt := awaitRollback(t, s, spec, "d1", upBase.Add(2*time.Minute))
60		v, _ := s.GetCampaign(spec.ID)
61		d := findDevice(v, "d1")
62		if d.Status != DeviceFailed || d.Phase != StageInstall {
63			t.Fatalf("legacy install failure: %+v", d)
64		}
65		if d.RollbackTarget != "" || d.RollbackResult {
66			t.Fatalf("legacy failure must not carry rollback state: %+v", d)
67		}
68		if !v.Ended || v.Status != CampaignFailed || !d.At.Equal(failAt) {
69			t.Fatalf("legacy campaign: %+v", v)
70		}
71		if v.RollbackOnFailure {
72			t.Fatal("view should report rollback disabled")
73		}
74		w, _ := s.GetDeviceWork("d1")
75		if w.Pending != nil || w.CampaignID != "" {
76			t.Fatalf("finished campaign has no work: %+v", w)
77		}
78	}
79	
80	// 首次领取下载时锁定设备当前版本为回滚目标；此后普通上报不得改变它。
81	func TestRollbackLocksVersionOnFirstDownloadClaim(t *testing.T) {
82		s := setupUpgrade(t, "d1")
83		spec := rbSpec()
84		createCampaign(t, s, spec)
85		bringOnline(t, s, "d1")
86	
