309	// 回滚成功附带的上报沿用序号/重复规则，版本必须等于锁定目标；
310	// 接受后更新当前版本与上报配置与回滚状态，保留期望配置、修订号与审计。
311	func TestRollbackSuccessReportAndShadow(t *testing.T) {
312		s := setupUpgrade(t, "d1")
313		spec := rbSpec()
314		createCampaign(t, s, spec)
315		bringOnline(t, s, "d1")
316		// 先设置期望配置，回滚后不得被升级前/上报配置覆盖。
317		rev, err := s.UpdateDesired("d1", "bob", upBase.Add(-2*time.Minute), 0, json.RawMessage(`{"x":1}`))
318		if err != nil || rev != 1 {
319			t.Fatalf("update desired: %v %d", err, rev)
320		}
321		awaitRollback(t, s, spec, "d1", upBase.Add(2*time.Minute))
322		rb, _ := s.Claim(spec.ID, "d1", upBase.Add(8*time.Minute))
323	
324		bad := func(mut func(*OperationResult)) {
325			t.Helper()
326			r := OperationResult{
327				CampaignID: spec.ID, DeviceID: "d1", OperationID: rb.ID,
328				At: upBase.Add(9 * time.Minute), Success: true,
329				Seq: 2, Version: "v1", Config: json.RawMessage(`{"x":2}`),
330			}
331			mut(&r)
332			if err := s.SubmitResult(r); !errors.Is(err, ErrInvalidReport) {
333				t.Fatalf("want ErrInvalidReport, got %v", err)
334			}
335		}
336		bad(func(r *OperationResult) { r.Seq = 0 })
337		bad(func(r *OperationResult) { r.Version = "v2" })
338		bad(func(r *OperationResult) { r.Version = "" })
339		bad(func(r *OperationResult) { r.Config = json.RawMessage(`[]`) })
340		bad(func(r *OperationResult) { r.Seq = 1; r.Config = json.RawMessage(`{"x":9}`) }) // 同序号内容冲突
341	
342		// 所有拒绝都不改影子、活动与历史。
343		view, _ := s.Get("d1")
344		if view.Version != "v1" || view.LastSeq != 1 || view.Revision != 1 {
345			t.Fatalf("shadow changed on rejected rollback: %+v", view)
346		}
347		cv, _ := s.GetCampaign(spec.ID)
348		if findDevice(cv, "d1").Status != DeviceRollingBack {
349			t.Fatalf("campaign changed on rejected rollback: %+v", findDevice(cv, "d1"))
350		}
351		historyBefore := len(cv.Results)
352	
353		// 合法回滚：窗口外、截止前提交。上报配置引入新的 /y 差异。
354		rbAt := upBase.Add(90 * time.Minute)
355		if err := s.SubmitResult(OperationResult{
356			CampaignID: spec.ID, DeviceID: "d1", OperationID: rb.ID,
357			At: rbAt, Success: true,
358			Seq: 2, Version: "v1", Config: json.RawMessage(`{"x":2,"y":9}`),
359		}); err != nil {
360			t.Fatalf("valid rollback: %v", err)
361		}
362		view, _ = s.Get("d1")
363		if view.Version != "v1" || !view.Online || view.LastSeq != 2 || string(view.Reported) != `{"x":2,"y":9}` {
364			t.Fatalf("shadow after rollback: %+v", view)
365		}
366		// 期望配置、修订号与审计保留。
367		if view.Revision != 1 || string(view.Desired) != `{"x":1}` {
368			t.Fatalf("desired/revision changed: %+v", view)
369		}
370		if auds, _ := s.Audit("d1"); len(auds) != 1 {
371			t.Fatalf("audit changed: %+v", auds)
372		}
373		// 配置差异按现有规则变化：/x 早已存在故保留原首次出现时间；
374		// /y 由回滚上报新引入，首次出现时间为回滚上报时间；不拿升级前配置覆盖期望。
375		diffs, _ := s.Diff("d1")
376		got := map[string]DiffEntry{}
377		for _, e := range diffs {
378			got[e.Path] = e
379		}
380		if len(got) != 2 {
381			t.Fatalf("diff after rollback: %+v", diffs)
382		}
383		if dx, ok := got["/x"]; !ok || !dx.Since.Equal(upBase.Add(-2*time.Minute)) {
384			t.Fatalf("/x keeps original since: %+v", got)
385		}
386		if dy, ok := got["/y"]; !ok || !dy.ReportedExists || !dy.Since.Equal(rbAt) {
387			t.Fatalf("/y first appears at rollback time: %+v", got)
388		}
389		cv, _ = s.GetCampaign(spec.ID)
390		if len(cv.Results) != historyBefore+1 {
391			t.Fatalf("history should grow by one rollback result")
392		}
393		if !cv.Ended || cv.Status != CampaignFailed {
394			t.Fatalf("campaign failed after rollback success: %+v", cv)
395		}
396	}
