492		if err := s.SubmitResult(OperationResult{
493			CampaignID: spec.ID, DeviceID: "d1", OperationID: rb.ID,
494			At: upBase.Add(61 * time.Minute), Success: true,
495			Seq: 2, Version: "v1", Config: json.RawMessage(`{}`),
