504	// 到达原截止时间：等待/正在回滚的设备以回滚阶段超时结束，不改写影子；
505	// 不再接收新结果；已接受结果的重复提交仍有效。
506	func TestRollbackDeadlineTimeout(t *testing.T) {
507		s := setupUpgrade(t, "d1", "d2")
508		spec := upSpec()
509		spec.Devices = []string{"d1", "d2"}
510		spec.BatchSize = 2
511		spec.RollbackOnFailure = true
512		createCampaign(t, s, spec)
513		bringOnline(t, s, "d1")
514		bringOnline(t, s, "d2")
515	
516		// d1 领取回滚并成功；d2 安装失败后停在等待回滚。
517		awaitRollback(t, s, spec, "d1", upBase.Add(2*time.Minute))
518		rb1, _ := s.Claim(spec.ID, "d1", upBase.Add(8*time.Minute))
519		rb1At := upBase.Add(9 * time.Minute)
520		if err := s.SubmitResult(OperationResult{
521			CampaignID: spec.ID, DeviceID: "d1", OperationID: rb1.ID,
522			At: rb1At, Success: true,
523			Seq: 2, Version: "v1", Config: json.RawMessage(`{}`),
524		}); err != nil {
525			t.Fatalf("d1 rollback: %v", err)
526		}
527		awaitRollback(t, s, spec, "d2", upBase.Add(12*time.Minute))
528		// d2 领取回滚但不完成（正在回滚）。
529		rb2, _ := s.Claim(spec.ID, "d2", upBase.Add(20*time.Minute))
530	
531		if err := s.AdvanceCampaign(spec.ID, upBase.Add(2*time.Hour)); err != nil {
532			t.Fatal(err)
533		}
534		v, _ := s.GetCampaign(spec.ID)
535		if !v.Ended || v.Status != CampaignFailed {
536			t.Fatalf("deadline ends campaign failed: %+v", v)
537		}
538		d2 := findDevice(v, "d2")
539		if d2.Status != DeviceRollbackTimeout || d2.Phase != StageRollback || d2.Reason == "" {
540			t.Fatalf("rolling-back device rollback-timeout: %+v", d2)
541		}
542		d1 := findDevice(v, "d1")
543		if d1.Status != DeviceRollbackSucceeded {
544			t.Fatalf("finished rollback kept: %+v", d1)
545		}
546		// 影子不被超时改写。
547		if sh, _ := s.Get("d2"); sh.Version != "v1" || sh.LastSeq != 1 {
548			t.Fatalf("shadow changed on timeout: %+v", sh)
549		}
550		// 不再接收新结果。
551		if err := s.SubmitResult(OperationResult{
552			CampaignID: spec.ID, DeviceID: "d2", OperationID: rb2.ID,
553			At: upBase.Add(2*time.Hour + time.Minute), Success: true,
554			Seq: 2, Version: "v1", Config: json.RawMessage(`{}`),
555		}); !errors.Is(err, ErrCampaignEnded) {
556			t.Fatalf("new rollback result after deadline: %v", err)
557		}
558		// 已接受结果的重复提交仍有效，不增加历史。
559		n := len(v.Results)
560		if err := s.SubmitResult(OperationResult{
561			CampaignID: spec.ID, DeviceID: "d1", OperationID: rb1.ID,
562			At: upBase.Add(3 * time.Hour), Success: true,
563			Seq: 2, Version: "v1", Config: json.RawMessage(`{}`),
564		}); err != nil {
565			t.Fatalf("accepted result replay after end: %v", err)
566		}
567		if cv, _ := s.GetCampaign(spec.ID); len(cv.Results) != n {
568			t.Fatal("replay after deadline added history")
569		}
570	}
571	
572	// 回滚未完成时的普通上报只更新影子，不替代回滚结果或清除待办；
573	// 回滚最终仍必须恢复到锁定版本。
574	func TestPlainReportDuringRollbackOnlyUpdatesShadow(t *testing.T) {
575		s := setupUpgrade(t, "d1")
576		spec := rbSpec()
577		createCampaign(t, s, spec)
578		bringOnline(t, s, "d1")
579		awaitRollback(t, s, spec, "d1", upBase.Add(2*time.Minute))
580	
581		// 等待回滚期间普通上报把版本/配置改成别的：影子更新，回滚待办不变。
582		if err := s.Report("d1", 2, upBase.Add(6*time.Minute), "v-stray", json.RawMessage(`{"a":1}`)); err != nil {
583			t.Fatal(err)
584		}
585		if sh, _ := s.Get("d1"); sh.Version != "v-stray" || sh.LastSeq != 2 {
586			t.Fatalf("plain report should update shadow: %+v", sh)
587		}
588		cv, _ := s.GetCampaign(spec.ID)
589		d := findDevice(cv, "d1")
590		if d.Status != DeviceAwaitingRollback || d.RollbackTarget != "v1" || d.RollbackResult {
591			t.Fatalf("plain report must not clear rollback todo: %+v", d)
592		}
593		w, _ := s.GetDeviceWork("d1")
594		if w.Pending == nil || w.Pending.Kind != StageRollback || w.PendingClaimed ||
595			w.Pending.TargetVersion != "v1" {
596			t.Fatalf("rollback todo survives plain report: %+v", w)
597		}
598		// 回滚成功以更大序号、锁定版本 v1 接受：影子回到锁定版本与上报配置。
599		rb, _ := s.Claim(spec.ID, "d1", upBase.Add(8*time.Minute))
600		if err := s.SubmitResult(OperationResult{
601			CampaignID: spec.ID, DeviceID: "d1", OperationID: rb.ID,
602			At: upBase.Add(9 * time.Minute), Success: true,
603			Seq: 3, Version: "v1", Config: json.RawMessage(`{"a":0}`),
604		}); err != nil {
605			t.Fatalf("rollback to locked target: %v", err)
606		}
607		if sh, _ := s.Get("d1"); sh.Version != "v1" || sh.LastSeq != 3 || string(sh.Reported) != `{"a":0}` {
608			t.Fatalf("shadow restored to locked target: %+v", sh)
609		}
610	}
611	
612	// 关闭重开保留回滚目标、进度、操作标识与重复判断，并可继续完成。
613	func TestRollbackPersistenceReopen(t *testing.T) {
614		s, dir := openTemp(t)
615		if err := s.RegisterUpgrade("v2", []string{"v1"}); err != nil {
616			t.Fatal(err)
617		}
618		mustRegister(t, s, "d1", "v1")
619		mustRegister(t, s, "d2", "v1")
620		spec := upSpec()
621		spec.Devices = []string{"d1", "d2"}
622		spec.BatchSize = 2
623		spec.RollbackOnFailure = true
624		createCampaign(t, s, spec)
625		bringOnline(t, s, "d1")
626		bringOnline(t, s, "d2")
627		_, failAt := awaitRollback(t, s, spec, "d1", upBase.Add(2*time.Minute))
628		rbBefore, _ := s.Claim(spec.ID, "d1", upBase.Add(8*time.Minute)) // 正在回滚
629		// d2 停在等待回滚。
630		awaitRollback(t, s, spec, "d2", upBase.Add(12*time.Minute))
631		if err := s.Close(); err != nil {
632			t.Fatal(err)
633		}
634	
635		s2, err := Open(dir)
636		if err != nil {
637			t.Fatal(err)
638		}
639		defer s2.Close()
640		v, err := s2.GetCampaign(spec.ID)
641		if err != nil {
642			t.Fatal(err)
643		}
644		if !v.RollbackOnFailure {
645			t.Fatal("rollback flag lost after reopen")
646		}
647		d1 := findDevice(v, "d1")
648		if d1.Status != DeviceRollingBack || d1.RollbackTarget != "v1" ||
649			d1.RollbackID != encodeOperationIDV2(0, spec.ID, "d1", StageRollback) || d1.InstallFailAt.IsZero() {
650			t.Fatalf("d1 rollback progress after reopen: %+v", d1)
651		}
652		if !d1.InstallFailAt.Equal(failAt) {
653			t.Fatalf("install failure time after reopen: %v", d1.InstallFailAt)
654		}
655		d2 := findDevice(v, "d2")
656		if d2.Status != DeviceAwaitingRollback || d2.RollbackTarget != "v1" {
657			t.Fatalf("d2 awaiting after reopen: %+v", d2)
658		}
659		// d2 待办显示回滚目标、未领取。
660		w, _ := s2.GetDeviceWork("d2")
661		if w.Pending == nil || w.Pending.Kind != StageRollback || w.PendingClaimed ||
662			w.Pending.TargetVersion != "v1" {
663			t.Fatalf("d2 work after reopen: %+v", w)
664		}
665		// d1 已领取的回滚再次领取仍是同一标识。
666		again, err := s2.Claim(spec.ID, "d1", upBase.Add(85*time.Minute))
667		if err != nil || again == nil || again.ID != rbBefore.ID {
668			t.Fatalf("stable rollback id after reopen: %v %+v", err, again)
669		}
670		// 时间倒退判断延续。
671		if err := s2.AdvanceCampaign(spec.ID, upBase.Add(7*time.Minute)); !errors.Is(err, ErrTimeRegression) {
672			t.Fatalf("regression after reopen: %v", err)
673		}
674		// 重复结果判断延续：回滚成功只接受一次，重放不增加历史。
675		res := OperationResult{
676			CampaignID: spec.ID, DeviceID: "d1", OperationID: rbBefore.ID,
677			At: upBase.Add(86 * time.Minute), Success: true,
678			Seq: 2, Version: "v1", Config: json.RawMessage(`{"ok":1}`),
679		}
680		if err := s2.SubmitResult(res); err != nil {
681			t.Fatalf("rollback after reopen: %v", err)
682		}
683		n := len(mustGetCampaign(s2, spec.ID).Results)
684		res.At = upBase.Add(87 * time.Minute)
685		if err := s2.SubmitResult(res); err != nil {
686			t.Fatalf("rollback replay: %v", err)
687		}
688		if len(mustGetCampaign(s2, spec.ID).Results) != n {
689			t.Fatal("rollback replay added history after reopen")
690		}
691		if sh, _ := s2.Get("d1"); sh.Version != "v1" {
692			t.Fatalf("shadow version after reopen rollback: %s", sh.Version)
693		}
694	}
695	
696	// 回滚成功涉及影子、活动与历史；保存失败时三者全部保持操作前结果。
697	func TestRollbackSaveFailureRollback(t *testing.T) {
698		s, dir := setupUpgradeDir(t, "d1")
699		spec := rbSpec()
700		createCampaign(t, s, spec)
