712			CampaignID: spec.ID, DeviceID: "d1", OperationID: rb.ID,
713			At: upBase.Add(9 * time.Minute), Success: true,
714			Seq: 2, Version: "v1", Config: json.RawMessage(`{"x":1}`),
715		})
716		if err == nil {
717			t.Fatal("expected save failure")
718		}
719		// 影子回滚。
