735		}
736		if err := s.SubmitResult(OperationResult{
737			CampaignID: spec.ID, DeviceID: "d1", OperationID: rb.ID,
738			At: upBase.Add(10 * time.Minute), Success: true,
739			Seq: 2, Version: "v1", Config: json.RawMessage(`{"x":1}`),
740		}); err != nil {
741			t.Fatalf("retry after recovery: %v", err)
742		}
743		if sh, _ := s.Get("d1"); sh.Version != "v1" || sh.LastSeq != 2 {
744			t.Fatalf("shadow after retry: %+v", sh)
745		}
746	}
747	
748	// 旧存储中的活动（无任何回滚字段）可直接打开，回滚缺省关闭并保持旧行为。
749	func TestOldCampaignStorageRollbackDefaultsOff(t *testing.T) {
