3	import (
4		"encoding/json"
5		"errors"
6		"testing"
7		"time"
8	)
9	
10	// endedSpec 构造一个窗口 12:00–12:09（[start,end)）、截止 12:10 的单/多设备活动。
11	func endedSpec(devices []string, batch int, rollback bool) CampaignSpec {
12		spec := upSpec()
13		spec.ID = "cmp-ended"
14		spec.Devices = devices
15		spec.BatchSize = batch
16		spec.WindowStart = upBase
17		spec.WindowEnd = upBase.Add(9 * time.Minute)
18		spec.Deadline = upBase.Add(10 * time.Minute) // 12:10
19		spec.RollbackOnFailure = rollback
20		return spec
21	}
22	
23	// 设备已领取安装，活动在 12:10 被 AdvanceCampaign 结束为超时；设备 12:20 的迟到
24	// 安装结果必须是不推进时间基线的纯拒绝（ErrCampaignEnded）。随后 12:15 的
25	// AdvanceCampaign 应按已结束活动规则成功返回，而不是 ErrTimeRegression；
26	// 活动结束时间、设备状态、结果历史与影子均保持 12:10 的样子。
27	func TestLateResultAfterTimeoutIsPureReject(t *testing.T) {
28		s := setupUpgrade(t, "d1")
29		spec := endedSpec([]string{"d1"}, 1, false)
30		createCampaign(t, s, spec)
31		bringOnline(t, s, "d1")
32		in := claimInstall(t, s, spec, "d1", upBase.Add(2*time.Minute)) // 12:04 已领取安装
33	
34		end := upBase.Add(10 * time.Minute) // 12:10
35		if err := s.AdvanceCampaign(spec.ID, end); err != nil {
36			t.Fatalf("advance to deadline: %v", err)
37		}
38		before, _ := s.GetCampaign(spec.ID)
39		if !before.Ended || !before.EndedAt.Equal(end) {
40			t.Fatalf("campaign not ended at deadline: %+v", before)
41		}
42		shadowBefore, _ := s.Get("d1")
43	
44		// 12:20 迟到的安装成功结果（附带上报完全合法也一样拒绝）。
45		err := s.SubmitResult(OperationResult{
46			CampaignID: spec.ID, DeviceID: "d1", OperationID: in,
47			At: upBase.Add(20 * time.Minute), Success: true,
48			Seq: 2, Version: "v2", Config: json.RawMessage(`{"ok":true}`),
49		})
50		if !errors.Is(err, ErrCampaignEnded) {
51			t.Fatalf("late result after end: %v", err)
52		}
53	
54		after, _ := s.GetCampaign(spec.ID)
55		if !after.Ended || after.Status != CampaignFailed || !after.EndedAt.Equal(end) {
56			t.Fatalf("campaign conclusion/end time changed: %+v", after)
57		}
58		d := findDevice(after, "d1")
59		if d.Status != DeviceTimeout || d.Phase != StageInstall ||
60			d.Reason == "" || !d.At.Equal(end) {
61			t.Fatalf("device state changed by rejected result: %+v", d)
62		}
63		if len(after.Results) != len(before.Results) {
64			t.Fatalf("rejected result added history: %d -> %d", len(before.Results), len(after.Results))
65		}
66		sh, _ := s.Get("d1")
67		if sh.Version != shadowBefore.Version || sh.Online != shadowBefore.Online ||
68			sh.Revision != shadowBefore.Revision || sh.LastSeq != shadowBefore.LastSeq ||
69			!rawEqual(sh.Desired, shadowBefore.Desired) || !rawEqual(sh.Reported, shadowBefore.Reported) {
70			t.Fatalf("shadow changed by rejected result: before %+v after %+v", shadowBefore, sh)
71		}
72	
73		// 12:15（早于被拒绝的 12:20、晚于结束时间 12:10）推进已结束活动必须成功。
74		if err := s.AdvanceCampaign(spec.ID, upBase.Add(15*time.Minute)); err != nil {
75			t.Fatalf("advance after rejected late result must not regress: %v", err)
76		}
77		final, _ := s.GetCampaign(spec.ID)
78		if !final.Ended || !final.EndedAt.Equal(end) {
79			t.Fatalf("advance altered ended campaign: %+v", final)
80		}
81	}
82	
83	// 活动结束后的迟到结果不校验内容：附带上报缺失、版本不符、配置非法、序号冲突，
84	// 以及失败结果缺少原因，都只返回 ErrCampaignEnded；不推进时间基线、不写影子。
85	func TestLateResultAfterTimeoutSkipsContentValidation(t *testing.T) {
86		cases := []struct {
87			name string
88			res  OperationResult
89		}{
90			{"missing report", OperationResult{Success: true}},
91			{"wrong version", OperationResult{Success: true, Seq: 2, Version: "v9", Config: json.RawMessage(`{}`)}},
92			{"bad config", OperationResult{Success: true, Seq: 2, Version: "v2", Config: json.RawMessage(`[1]`)}},
93			{"seq conflict", OperationResult{Success: true, Seq: 1, Version: "v2", Config: json.RawMessage(`{"x":1}`)}},
94			{"failure without reason", OperationResult{Success: false}},
95		}
96		for _, tc := range cases {
97			t.Run(tc.name, func(t *testing.T) {
98				s := setupUpgrade(t, "d1")
99				spec := endedSpec([]string{"d1"}, 1, false)
100				createCampaign(t, s, spec)
101				bringOnline(t, s, "d1")
102				in := claimInstall(t, s, spec, "d1", upBase.Add(2*time.Minute))
103				end := upBase.Add(10 * time.Minute)
104				if err := s.AdvanceCampaign(spec.ID, end); err != nil {
105					t.Fatal(err)
106				}
107				nResults := len(mustGetCampaign(s, spec.ID).Results)
108	
109				res := tc.res
110				res.CampaignID = spec.ID
111				res.DeviceID = "d1"
112				res.OperationID = in
113				res.At = upBase.Add(20 * time.Minute)
114				if err := s.SubmitResult(res); !errors.Is(err, ErrCampaignEnded) {
115					t.Fatalf("got %v, want ErrCampaignEnded", err)
116				}
117				cv, _ := s.GetCampaign(spec.ID)
118				if !cv.Ended || !cv.EndedAt.Equal(end) ||
119					findDevice(cv, "d1").Status != DeviceTimeout ||
120					len(cv.Results) != nResults {
121					t.Fatalf("rejected result changed campaign: %+v", cv)
122				}
123				// 拒绝不得推进时间基线：12:15 仍合法。
124				if err := s.AdvanceCampaign(spec.ID, upBase.Add(15*time.Minute)); err != nil {
125					t.Fatalf("rejection advanced time baseline: %v", err)
126				}
127			})
128		}
129	}
130	
131	// 已领取下载、尚未完成的设备在活动超时结束后迟到提交下载结果，同样是纯拒绝。
132	func TestLateDownloadResultAfterTimeoutIsPureReject(t *testing.T) {
133		s := setupUpgrade(t, "d1")
134		spec := endedSpec([]string{"d1"}, 1, false)
135		createCampaign(t, s, spec)
136		bringOnline(t, s, "d1")
137		dl, err := s.Claim(spec.ID, "d1", upBase.Add(2*time.Minute)) // 下载中
138		if err != nil || dl == nil || dl.Kind != StageDownload {
139			t.Fatalf("claim download: %v %+v", err, dl)
140		}
141		end := upBase.Add(10 * time.Minute)
142		if err := s.AdvanceCampaign(spec.ID, end); err != nil {
143			t.Fatal(err)
144		}
145	
146		if err := s.SubmitResult(OperationResult{
147			CampaignID: spec.ID, DeviceID: "d1", OperationID: dl.ID,
148			At: upBase.Add(20 * time.Minute), Success: true,
149		}); !errors.Is(err, ErrCampaignEnded) {
150			t.Fatalf("late download after end: %v", err)
151		}
152		cv, _ := s.GetCampaign(spec.ID)
153		d := findDevice(cv, "d1")
154		if d.Status != DeviceTimeout || d.Phase != StageDownload || !d.At.Equal(end) ||
155			!cv.EndedAt.Equal(end) {
156			t.Fatalf("state changed by rejected download: %+v / %+v", d, cv)
157		}
158		if err := s.AdvanceCampaign(spec.ID, upBase.Add(15*time.Minute)); err != nil {
159			t.Fatalf("rejection advanced time baseline: %v", err)
160		}
161	}
162	
163	// 已超时活动中正在回滚（回滚已领取）的设备迟到提交回滚结果：纯拒绝、影子不变；
164	// 仍在等待回滚（回滚未领取）的设备提交回滚标识按未领取拒绝。两者都不推进时间。
165	func TestLateRollbackResultAfterTimeoutIsPureReject(t *testing.T) {
166		s := setupUpgrade(t, "d1", "d2")
167		spec := endedSpec([]string{"d1", "d2"}, 2, true)
168		createCampaign(t, s, spec)
169		bringOnline(t, s, "d1")
170		bringOnline(t, s, "d2")
171		// d1 走到等待回滚后再领取回滚（正在回滚，12:05）；d2 停在等待回滚（12:08）。
172		awaitRollback(t, s, spec, "d1", upBase.Add(1*time.Minute))
173		rbClaimed, err := s.Claim(spec.ID, "d1", upBase.Add(5*time.Minute))
174		if err != nil || rbClaimed == nil || rbClaimed.Kind != StageRollback {
175			t.Fatalf("claim rollback d1: %v %+v", err, rbClaimed)
176		}
177		awaitRollback(t, s, spec, "d2", upBase.Add(5*time.Minute))
178	
179		end := upBase.Add(10 * time.Minute)
180		if err := s.AdvanceCampaign(spec.ID, end); err != nil {
181			t.Fatal(err)
182		}
183		cv0, _ := s.GetCampaign(spec.ID)
184		nResults := len(cv0.Results)
185		d2RollbackID := findDevice(cv0, "d2").RollbackID
186	
187		// d1 已领取回滚的迟到成功结果（附带上报合法）：纯拒绝，影子不被改回锁定版本。
188		if err := s.SubmitResult(OperationResult{
189			CampaignID: spec.ID, DeviceID: "d1", OperationID: rbClaimed.ID,
190			At: upBase.Add(20 * time.Minute), Success: true,
191			Seq: 2, Version: "v1", Config: json.RawMessage(`{}`),
192		}); !errors.Is(err, ErrCampaignEnded) {
193			t.Fatalf("late rollback after end: %v", err)
194		}
195		// d2 尚未领取回滚：按既有未领取规则拒绝，而不是活动已结束。
196		if err := s.SubmitResult(OperationResult{
197			CampaignID: spec.ID, DeviceID: "d2", OperationID: d2RollbackID,
198			At: upBase.Add(20 * time.Minute), Success: true,
199			Seq: 2, Version: "v1", Config: json.RawMessage(`{}`),
200		}); !errors.Is(err, ErrOperationNotClaimed) {
201			t.Fatalf("unclaimed rollback after end: %v", err)
202		}
203	
204		cv, _ := s.GetCampaign(spec.ID)
205		d1 := findDevice(cv, "d1")
206		d2 := findDevice(cv, "d2")
207		if d1.Status != DeviceRollbackTimeout || !d1.At.Equal(end) ||
208			d2.Status != DeviceRollbackTimeout || !d2.At.Equal(end) ||
209			!cv.EndedAt.Equal(end) || len(cv.Results) != nResults {
