	}
	in, err := s.Claim(spec.ID, id, at.Add(2*time.Minute))
	if err != nil {
		t.Fatalf("claim install %s: %v", id, err)
	}
	if in == nil || in.Kind != StageInstall {
		t.Fatalf("want install op for %s, got %+v", id, in)
